components.css:
.ds-button {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-height: 50px;
	padding: 13px 20px;
	border-radius: 12px;
	font-size: 16px;
	font-weight: 700;
	line-height: 1.3;
	transition: transform 160ms ease, background 160ms ease, border-color 160ms ease;
}
.ds-button:hover {
	transform: translateY(-2px);
}
.ds-button-primary {
	background: var(--color-accent);
	color: #090a0d;
}
.ds-button-primary:hover {
	background: #a7b3ff;
}
.ds-button {font-family:var(--font-sans, Arial, Helvetica, sans-serif);text-decoration:none;}
.ds-button:focus-visible {outline:3px solid var(--color-accent,#91a2ff);outline-offset:4px;}

