.ds-submit { display: inline-flex; align-items: center; justify-content: center; gap: 12px; justify-self: start; min-height: 48px; padding: 12px 20px; border: 0; border-radius: 10px; background: var(--color-accent); color: var(--color-page); font: inherit; font-size: 16px; font-weight: 700; cursor: pointer; transition: background 160ms ease; }
.ds-submit:hover:enabled { background: #b5c0ff; }
.ds-submit:disabled { opacity: 0.55; cursor: not-allowed; }
.ds-submit { width: 100%; }
.ds-submit {font-family:var(--font-sans, Arial, Helvetica, sans-serif);}
.ds-submit:focus-visible {outline:3px solid var(--color-accent,#91a2ff);outline-offset:4px;}

.ds-label {display:block;margin-bottom:8px;font-size:15px;font-weight:700;color:var(--color-primary,#f5f7fa);font-family:var(--font-sans, Arial, Helvetica, sans-serif);}
.ds-input, .ds-textarea { width: 100%; min-width: 0; padding: 12px 14px; border: 1px solid #555c6f; border-radius: 10px; background: var(--color-elevated); color: var(--color-primary); font: inherit; font-size: 16px; line-height: 1.5; caret-color: var(--color-accent); }
.ds-input[aria-invalid="true"], .ds-textarea[aria-invalid="true"] { border-color: #ffb4bd; }
.ds-input {font-family:var(--font-sans, Arial, Helvetica, sans-serif);}
.ds-input:focus-visible {outline:3px solid var(--color-accent,#91a2ff);outline-offset:3px;}

.ds-footer {
	display: flex;
	width: 100%;
	min-height: 52px;
	align-items: center;
	gap: 16px;
	border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.ds-footer a {
	color: var(--color-secondary);
	font-size: 14px;
	font-weight: 600;
	transition: color 160ms ease;
}
.ds-footer a:hover {
	color: var(--color-primary);
}
.ds-footer {
		flex-wrap: wrap;
		justify-content: center;
		padding-block: 12px;
	}
.ds-footer {font-family:var(--font-sans, Arial, Helvetica, sans-serif);flex-wrap:wrap;} .ds-footer a {text-decoration:none;} .ds-footer a:focus-visible {outline:3px solid var(--color-accent,#91a2ff);outline-offset:4px;}
